===OwnerRegion===
package org.springframework.samples.petclinic.util;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The canonical region ("locality") of an owner: the region derived from its postcode
 * first (see {@link PostcodeRange#regionOf(String)}), falling back to the city-to-region
 * table when the postcode is absent or in no known range, or {@link CityRegion#UNKNOWN}
 * for a city not in the table.
 *
 * <p>This region is the {@code REGION} segment of the owner's customer-code identity (see
 * {@link CustomerCode}); the identity is built from it on creation and the locality read
 * back off it, so there is one region concept rather than two derivations that could drift.
 */
public final class OwnerRegion {

    private OwnerRegion() {
    }

    /** The region for the given owner, derived from its postcode then its city. */
    public static String of(Owner owner) {
        String byPostcode = PostcodeRange.regionOf(owner.getPostcode());
        return byPostcode != null ? byPostcode : CityRegion.localityOf(owner.getCity());
    }
}
===MembershipLevel===
package org.springframework.samples.petclinic.util;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Maps an owner's {@link MembershipPoints} score to a numeric membership level: level 1
 * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more points.
 *
 * <p>An owner may carry a household level ceiling ({@link Owner#getMembershipLevelCap()});
 * when present it caps the effective level, so a new owner never outranks the highest of
 * their existing household members by more than one.
 */
public final class MembershipLevel {

    /** Lowest level attainable. */
    public static final int MIN = 1;

    /** Highest level attainable. */
    public static final int MAX = 4;

    private MembershipLevel() {
    }

    /** The membership level for the given owner as of today. */
    public static int of(Owner owner) {
        return of(owner, LocalDate.now());
    }

    /** The membership level for the given owner, with tenure measured as of {@code asOf}.
     *  Limited by the owner's stored household level ceiling when one is set. */
    public static int of(Owner owner, LocalDate asOf) {
        return capped(forPoints(MembershipPoints.of(owner, asOf)), owner.getMembershipLevelCap());
    }

    /** Apply a household level ceiling: {@code cap} (when non-null) limits {@code level}. */
    private static int capped(int level, Integer cap) {
        return cap == null ? level : Math.min(level, cap);
    }

    /** The membership level for a given membership points score. */
    public static int forPoints(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }
}
===CityRegion===
package org.springframework.samples.petclinic.util;

import java.util.Locale;
import java.util.Map;

/**
 * Fixed lookup from an owner's city to its canonical region (its "locality"). The table
 * is pinned; any city not listed has locality {@link #UNKNOWN}.
 */
public final class CityRegion {

    /** The locality returned for any city not present in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    /** City (matched case-insensitively) to canonical region string. */
    private static final Map<String, String> CITY_REGION = Map.of(
        "sydney", "NSW",
        "melbourne", "VIC",
        "brisbane", "QLD");

    private CityRegion() {
    }

    /**
     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
     * in the table. Matching is case-insensitive; a null city is {@link #UNKNOWN}.
     */
    public static String localityOf(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city.toLowerCase(Locale.ROOT), UNKNOWN);
    }
}

